--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: deduct_inventory_on_order(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deduct_inventory_on_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- Only act on freshly inserted order items (new orders)
  -- Reduce stock for the variant
  update public.store_product_variants
  set
    stock_quantity   = greatest(0, stock_quantity - NEW.quantity),
    availability     = case
                         when greatest(0, stock_quantity - NEW.quantity) = 0
                         then 'out_of_stock'
                         else availability
                       end,
    updated_at       = now()
  where id = NEW.variant_id;

  return NEW;
end;
$$;


ALTER FUNCTION public.deduct_inventory_on_order() OWNER TO postgres;

--
-- Name: enforce_single_default_address(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_single_default_address() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.is_default then
    update public.store_delivery_profiles
      set is_default = false
      where user_id = new.user_id
        and id <> new.id
        and is_default = true;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.enforce_single_default_address() OWNER TO postgres;

