--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.user_settings (user_id, name, pending_email_verify)
  VALUES (
    new.id,
    COALESCE(new.raw_user_meta_data->>'name', ''),
    -- signUpWithEmail() (manual signup) tags new accounts with
    -- signup_method: 'manual' in options.data (see src/lib/auth.tsx).
    -- signInWithGoogle() never sets this, so Google accounts correctly
    -- default to false (not pending) here, atomically, at creation time.
    COALESCE(new.raw_user_meta_data->>'signup_method', '') = 'manual'
  )
  ON CONFLICT (user_id) DO NOTHING;
  RETURN new;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

--
-- Name: is_store_admin(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_store_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    (select is_store_admin from public.user_settings where user_id = auth.uid()),
    false
  );
$$;


ALTER FUNCTION public.is_store_admin() OWNER TO postgres;

--
-- Name: mark_password_set(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_password_set(p_user_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  INSERT INTO public.user_settings (user_id, password_set)
  VALUES (p_user_id, true)
  ON CONFLICT (user_id) DO UPDATE SET password_set = true;
$$;


ALTER FUNCTION public.mark_password_set(p_user_id uuid) OWNER TO postgres;

--
-- Name: prevent_self_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_self_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  acting_is_admin boolean;
begin
  -- (a) Server-side writes (service role) and (b) the SQL editor /
  -- superuser sessions are always trusted.
  if auth.role() = 'service_role' or current_user in ('postgres', 'service_role') then
    return new;
  end if;

  -- From here on this is an ordinary end-user request arriving through
  -- the anon/authenticated Postgres role (i.e. the browser's Supabase
  -- client, straight from devtools or the app). Only an existing admin
  -- may change these flags — never the user acting on their own row.
  select coalesce(is_store_admin, false)
    into acting_is_admin
    from public.user_settings
   where user_id = auth.uid();

  if not coalesce(acting_is_admin, false) then
    if new.is_store_admin is distinct from old.is_store_admin then
      raise exception 'Not authorized to change is_store_admin';
    end if;
    if new.pending_email_verify is distinct from old.pending_email_verify then
      raise exception 'Not authorized to change pending_email_verify';
    end if;
    if new.password_set is distinct from old.password_set then
      raise exception 'Not authorized to change password_set';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION public.prevent_self_privilege_escalation() OWNER TO postgres;

--
-- Name: rename_product_group(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rename_product_group(p_id uuid, p_new_name text, p_new_slug text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.product_groups
  set name = p_new_name, slug = p_new_slug, updated_at = now()
  where id = p_id;
end;
$$;


ALTER FUNCTION public.rename_product_group(p_id uuid, p_new_name text, p_new_slug text) OWNER TO postgres;

--
-- Name: rename_product_type(uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rename_product_type(p_id uuid, p_new_name text, p_new_slug text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update public.product_types
  set name = p_new_name, slug = p_new_slug, updated_at = now()
  where id = p_id;
  update public.store_products
  set product_type = p_new_name, updated_at = now()
  where product_type_id = p_id;
end;
$$;


ALTER FUNCTION public.rename_product_type(p_id uuid, p_new_name text, p_new_slug text) OWNER TO postgres;

--
-- Name: restore_inventory_on_cancel(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_inventory_on_cancel() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  -- Only act when status transitions TO 'cancelled' from a non-cancelled state
  if NEW.status = 'cancelled' and OLD.status != 'cancelled' then
    -- Restore stock for each item in the order
    update public.store_product_variants v
    set
      stock_quantity = v.stock_quantity + oi.quantity,
      availability   = case
                         when v.availability = 'out_of_stock'
                         then 'active'
                         else v.availability
                       end,
      updated_at     = now()
    from public.store_order_items oi
    where oi.order_id = NEW.id
      and oi.variant_id = v.id;
  end if;

  return NEW;
end;
$$;


ALTER FUNCTION public.restore_inventory_on_cancel() OWNER TO postgres;

--
-- Name: rls_auto_enable(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.rls_auto_enable() RETURNS event_trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION public.rls_auto_enable() OWNER TO postgres;

