--
-- Name: store_low_stock_variants; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.store_low_stock_variants WITH (security_invoker='true') AS
 SELECT v.id AS variant_id,
    v.sku,
    v.name AS variant_name,
    v.stock_quantity,
    v.low_stock_threshold,
    v.availability,
    p.id AS product_id,
    p.name AS product_name
   FROM (public.store_product_variants v
     JOIN public.store_products p ON ((p.id = v.product_id)))
  WHERE ((v.stock_quantity <= v.low_stock_threshold) AND (p.published = true) AND (EXISTS ( SELECT 1
           FROM public.user_settings
          WHERE ((user_settings.user_id = auth.uid()) AND (user_settings.is_store_admin = true)))))
  ORDER BY v.stock_quantity;


ALTER VIEW public.store_low_stock_variants OWNER TO postgres;

