    customer_name text NOT NULL,
    customer_email text NOT NULL,
    customer_phone text DEFAULT ''::text NOT NULL,
    delivery_address jsonb DEFAULT '{}'::jsonb NOT NULL,
    payment_method text DEFAULT 'cod'::text NOT NULL,
    payment_status text DEFAULT 'pending'::text NOT NULL,
    payment_reference text,
    subtotal_paise bigint DEFAULT 0 NOT NULL,
    discount_paise bigint DEFAULT 0 NOT NULL,
    delivery_paise bigint DEFAULT 0 NOT NULL,
    total_paise bigint DEFAULT 0 NOT NULL,
    status text DEFAULT 'placed'::text NOT NULL,
    notes text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    razorpay_order_id text,
    razorpay_payment_id text,
    razorpay_signature text,
    payment_error text,
    CONSTRAINT store_orders_payment_method_check CHECK ((payment_method = ANY (ARRAY['razorpay'::text, 'upi'::text, 'card'::text, 'netbanking'::text, 'wallet'::text, 'emi'::text, 'cod'::text, 'other'::text]))),
    CONSTRAINT store_orders_payment_status_check CHECK ((payment_status = ANY (ARRAY['pending'::text, 'paid'::text, 'failed'::text, 'refunded'::text]))),
    CONSTRAINT store_orders_status_check CHECK ((status = ANY (ARRAY['placed'::text, 'confirmed'::text, 'processing'::text, 'shipped'::text, 'delivered'::text, 'cancelled'::text])))
);


ALTER TABLE public.store_orders OWNER TO postgres;

--
-- Name: store_order_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.store_order_summary WITH (security_invoker='true') AS
 SELECT count(*) FILTER (WHERE (status = 'placed'::text)) AS pending_count,
    count(*) FILTER (WHERE (status = 'confirmed'::text)) AS confirmed_count,
    count(*) FILTER (WHERE (status = 'processing'::text)) AS processing_count,
    count(*) FILTER (WHERE (status = 'shipped'::text)) AS shipped_count,
    count(*) FILTER (WHERE (status = 'delivered'::text)) AS delivered_count,
    count(*) FILTER (WHERE (status = 'cancelled'::text)) AS cancelled_count,
    count(*) AS total_orders,
    COALESCE(sum(total_paise) FILTER (WHERE (status <> 'cancelled'::text)), (0)::numeric) AS total_revenue_paise,
    COALESCE(sum(total_paise) FILTER (WHERE ((status <> 'cancelled'::text) AND (created_at >= date_trunc('month'::text, now())))), (0)::numeric) AS monthly_revenue_paise
   FROM public.store_orders
  WHERE (EXISTS ( SELECT 1
           FROM public.user_settings
          WHERE ((user_settings.user_id = auth.uid()) AND (user_settings.is_store_admin = true))));


ALTER VIEW public.store_order_summary OWNER TO postgres;

