-- Name: store_offers Admins manage offers; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Admins manage offers" ON public.store_offers USING ((EXISTS ( SELECT 1
   FROM public.user_settings
  WHERE ((user_settings.user_id = auth.uid()) AND (user_settings.is_store_admin = true))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public.user_settings
  WHERE ((user_settings.user_id = auth.uid()) AND (user_settings.is_store_admin = true)))));


